if (state.running) {
  // Capture where the ball was BEFORE this step: the brick sweep needs it
  // to catch tunnelling (fix #1).
  const prevX = state.ball.x;
  const prevY = state.ball.y;

  const lost = step(state, dt);
  if (lost) {
    state.lives -= 1;
    state.combo = 0;
    if (state.lives <= 0) {
      state.best = saveBest(globalThis.localStorage, state.score);
      Object.assign(state, createState(state.level));
      state.best = loadBest(globalThis.localStorage);
    } else {
      // relaunch the ball
      state.ball = createState(state.level).ball;
    }
  } else {
    // Brick physics + scoring in one pure call (fix #1).
    const hits = resolveBrickCollision(state.ball, prevX, prevY, state.bricks);
    for (const brick of hits) {
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
    }
  }

  // Level cleared: all bricks broken
  if (state.bricks.every((b) => !b.alive)) {
    state.level += 1;
    state.bricks = makeBricks(state.level);
    state.ball = createState(state.level).ball;
  }
}

