  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

edits.newText:
test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- #1 brick bounce -------------------------------------------------------
// Each case of ISSUES #1 is exercised here: per-face, corner, push out,
// neighbour seams (no double flip) and tunnelling at high speed.

function brickAt(x, y) {
  return { x, y, w: 40, h: 20, alive: true };
}

function ballAt(x, y, vx, vy) {
  return { x, y, r: 7, vx, vy };
}

test('brick hit from the top flips only vy (per face)', () => {
  const brick = brickAt(100, 100);
  const ball = ballAt(120, 120, 0, 300); // 120+7 = 127 > 100 => overlaps top
  // Ball centre sits just inside the top face: smaller penetration is vertical.
  const hits = resolveBrickCollision(ball, 120, 80, [brick]);
  assert.equal(hits.length, 1);
  assert.ok(ball.vy < 0, 'vertical velocity should bounce upward');
  assert.equal(ball.vx, 0, 'horizontal velocity untouched by a top hit');
  assert.ok(ball.y + ball.r <= brick.y, 'ball pushed back above the brick');
});

test('brick hit from the side flips only vx (per face)', () => {
  const brick = brickAt(100, 100);
  const ball = ballAt(87, 110, 80, 0); // 87+7 = 94 < 100, left of brick
  // Send it in from the left so it overlaps horizontally, not vertically.
  const ballV = ballAt(90, 110, 80, 0);
  const hits = resolveBrickCollision(ballV, 84, 110, [brick]);
  assert.equal(hits.length, 1);
  assert.ok(ballV.vx < 0, 'horizontal velocity should bounce back left');
  assert.equal(ballV.vy, 0, 'vertical velocity untouched by a side hit');
  assert.ok(ballV.x + ballV.r <= brick.x, 'ball pushed back left of the brick');
});

test('corner hit flips both components', () => {
  const brick = brickAt(100, 100);
  const ball = ballAt(94, 114, -50, 120); // overlaps the top-left corner
  const hits = resolveBrickCollision(ball, 94, 90, [brick]);
  assert.equal(hits.length, 1);
  assert.notEqual(ball.vx, -50, 'corner reverses x');
  assert.ok(ball.vy < 0, 'corner reverses y upward');
});

test('push out: ball no longer overlaps any destroyed brick', () => {
  const brick = brickAt(100, 100);
  const ball = ballAt(120, 120, 0, 300);
  resolveBrickCollision(ball, 120, 80, [brick]);
  assert.equal(brick.alive, false);
  assert.equal(collides(ball, brick), false, 'ball must be outside after bounce');
});

test('neighbour seam: velocity is NOT cancelled by a double flip', () => {
  // Two bricks sharing a seam; the 14px ball overlaps both at once. Sign of vy
  // must be preserved (flipped exactly once), not flipped back.
  const left = brickAt(100, 100);
  const right = brickAt(140, 100);
  const ball = ballAt(137, 110, 0, 250); // overlaps both horizontally
  const hits = resolveBrickCollision(ball, 137, 95, [left, right]);
  assert.equal(hits.length, 2, 'both seam bricks are broken');
  assert.ok(ball.vy < 0, 'vy inverted once, not twice');
});

test('tunnelling: high-speed step still catches a thin brick', () => {
  // Level 6 speed: a 50 ms stutter moves the ball ~35 px, far more than the
  // ~34 px needed to cross a row. The swept path must not skip the brick.
  const brick = brickAt(300, 100);
  const prev = ballAt(300, 130, 0, 0); // above the brick, resting
  const ball = ballAt(300, 70, 0, -710); // jumped right through 60+ px
  const hits = resolveBrickCollision(ball, prev.x, prev.y, [brick]);
  assert.equal(hits.length, 1, 'brick must be caught across the jump');
  assert.ok(ball.vy > 0, 'ball bounces back down after tunnelling');
});

