// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Brick bounce (pure, tested primitive) --------------------------------
//
// Resolves the ball bouncing off bricks. Given the ball's position at the
// START of the step (`prevX`, `prevY`) and its position after the step, this
// decides which brick was hit first, deflects the ball and pushes it back out
// so it never sticks. Returns every brick the ball broke in this step (their
// `alive` flag is set to `false` here so the caller can also score them).
//
// Horizontal velocity is always left untouched by a top/bottom hit and
// vertical velocity untouched by a side hit (ISSUES #1 "per face"). Because we
// pick a SINGLE primary brick, a seam hit (the ball overlaps two neighbouring
// bricks at once, gap 8 px vs. a 14 px ball) only flips the velocity once,
// instead of `vy = -vy` twice cancelling out.
//
// `segmentEntry` computes the first contact `t` of the ball's swept path with
// the brick inflated by the ball's radius, which is what makes discrete steps
// (ISSUES #1 "tunnelling") unable to skip over a brick at high speed.
export function resolveBrickCollision(ball, prevX, prevY, bricks) {
  const candidates = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const t = segmentEntry(prevX, prevY, ball.x, ball.y, brick, ball.r);
    if (t !== null) candidates.push({ brick, t });
  }
  if (candidates.length === 0) return [];

  // The brick hit first (smallest entry parameter) drives the single bounce.
  candidates.sort((a, b) => a.t - b.t);
  const primary = candidates[0];

  // Tunnelled hit: rewind the ball to the point of contact so it truly rests
  // against the face instead of having skipped past it.
  if (primary.t > 1e-9) {
    const dx = ball.x - prevX;
    const dy = ball.y - prevY;
    ball.x = prevX + dx * primary.t;
    ball.y = prevY + dy * primary.t;
  }

  bounceOff(ball, primary.brick);

  // Every brick the swept path touched has been broken.
  return candidates.map((candidate) => {
    candidate.brick.alive = false;
    return candidate.brick;
  });
}

// First contact of the ball's swept segment with the brick's rect inflated by
// the ball radius. Returns the entry parameter in [0, 1], or `null` when the
// path never touches the rect. This is a Liang–Barsky slab test, extended to a
// zero-length step and to a ball that already overlaps the rect (t = 0).
function segmentEntry(x0, y0, x1, y1, brick, r) {
  const rx = brick.x - r;
  const ry = brick.y - r;
  const rw = brick.w + 2 * r;
  const rh = brick.h + 2 * r;
  const dx = x1 - x0;
  const dy = y1 - y0;

  let tmin = 0;
  let tmax = 1;

  if (Math.abs(dx) < 1e-9) {
    if (x0 < rx || x0 > rx + rw) return null;
  } else {
    let t1 = (rx - x0) / dx;
    let t2 = (rx + rw - x0) / dx;
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; }
    tmin = Math.max(tmin, t1);
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return null;
  }

  if (Math.abs(dy) < 1e-9) {
    if (y0 < ry || y0 > ry + rh) return null;
  } else {
    let t1 = (ry - y0) / dy;
    let t2 = (ry + rh - y0) / dy;
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; }
    tmin = Math.max(tmin, t1);
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return null;
  }

  return tmin;
}

